    "name": "device_standby",
    "description": "Put one or more devices into standby mode. This tool puts compatible devices like TVs, media players, and gaming consoles into a low-power state while maintaining network connectivity. Devices in standby can be quickly reactivated and may perform background tasks like updates or content downloads.",
    "parameters": {
        "type": "object",
        "properties": {
            "endpoints": {
                "type": "array",
                "items": {
                    "type": "string"
                },
                "description": "List of device endpoint IDs to put into standby mode. Each endpoint must correspond to a device that supports the device_standby API."
            }
        },
        "required": ["endpoints"]
    },
    "error_cases": [
        "No devices specified: The endpoints parameter is empty or not provided.",
        "Device not found: One or more specified endpoints do not exist in the current user's home.",
        "API not supported: One or more devices do not support the device_standby API.",
        "State update failure: The device state could not be updated due to a system error."
    ]
